mapper.select:
select n.note_id ,n.note_type_lk ,n.note_date ,n.subject ,n.comments ,n.file_name ,n.create_user_id ,n.record_status_lk ,n.last_change_date ,coalesce(concat(owner.first_name, ' ', owner.last_name), 'Archived') as owner_name ,CASE WHEN has_read_flg.related_id is not null THEN 1 ELSE 0 END as read_flg from notes n left join users owner on owner.user_id = n.create_user_id and owner.record_status_lk != 'DL' join lk_note_types lknt on lknt.note_type_lk = n.note_type_lk left join (SELECT related_id from user_activities where create_user_id = #{userId} and activity_lk = 'GET_NOTE' LIMIT 1) has_read_flg on has_read_flg.related_id = n.note_id where n.record_status_lk = 'AP' and lknt.active_flg = 1
and exists(select * from note_references nr where nr.note_id = n.note_id and CONCAT('[', nr.reference_type_lk, '_', nr.reference_id, ']') in (
#{tagKey}
))
and n.create_user_id in (
#{userIds}
)
and n.note_date >= #{form.dateFrom}
and n.note_date <= #{form.dateTo}
and n.note_type_lk = #{form.noteTypeLk}
and n.attachment is not null
and n.attachment is null
order by n.note_date desc, n.create_date desc LIMIT (#{form.limit})

select distinct nr.note_reference_id ,nr.note_id ,nr.reference_type_lk ,nr.reference_id ,case when nr.reference_type_lk = 'PERSON' then p.display_name else COALESCE(concat(u.first_name, ' ', u.last_name), 'Archived') end as display_name ,case when ( case when nr.reference_type_lk = 'PERSON' then p.record_status_lk else u.record_status_lk end ) = 'AP' then 1 else 0 end as active_flg from note_references nr left join notes n on n.note_id = nr.note_id left join persons p on p.person_id = nr.reference_id and nr.reference_type_lk = 'PERSON' left join users u on u.user_id = nr.reference_id and nr.reference_type_lk = 'USER' and u.record_status_lk != 'DL'
and nr.note_id in (
#{noteId}
)

delete.if:
	 delete from notes
     where note_id in (

          #{noteId}

      )

	 delete from note_references
     where note_id in (

          #{noteId}

      )
